package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.function.owner.MissingOwnerFieldsException;

/**
 * Responds 400 with a JSON body whose {@code errors} array lists each missing or blank
 * required owner field.
 */
public class MissingOwnerFieldsExceptionHandler {

    public void handle(@Parameter MissingOwnerFieldsException ex,
            ObjectResponse<ResponseEntity<Errors>> response) {
        response.send(ResponseEntity.badRequest().body(new Errors(ex.getFields())));
    }

    /** Response body: {@code {"errors": ["city", ...]}}. */
    public static class Errors {

        private final java.util.List<String> errors;

        public Errors(java.util.List<String> errors) {
            this.errors = errors;
        }

        public java.util.List<String> getErrors() {
            return this.errors;
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects an owner create request that is missing or blank in any required field
 * (firstName, lastName, address, city, telephone) with a 400 whose body lists the
 * offending field names. Runs first in the pipeline and publishes the body for
 * {@link BuildOwner} once it is known to be complete.
 *
 * <p>Binds the body WITHOUT {@code @Valid} so a missing/blank field surfaces as a
 * {@link MissingOwnerFieldsException} (an {@code errors} array) rather than a bean
 * validation escalation.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
